type Store = { profile: Profile | null; chats: Message[]; results: Result[]; tasks: Task[]; topics: string[]; cards: Flashcard[]; theme: 'light' | 'dark'; revisions: Revision[]; mistakes: Mistake[]; savedResources: SavedResource[]; savedVisuals: string[]; completedVisuals: VisualCompleted[]; gamification: Gamification; pomodoro: PomodoroState };
const defaultGamification = (): Gamification => ({ xp: 0, xpToday: 0, xpDate: '', streak: 0, longestStreak: 0, lastActiveDate: '', missionDate: '', missionProgress: {}, missionClaimed: [], xpHistory: [], achievements: [], seen: [], stats: {} });
const defaultPomodoro = (): PomodoroState => ({ prefs: { focusMin: 25, shortMin: 5, longMin: 15, autoSwitch: true, longBreakEvery4: true }, runtime: { status: 'idle', mode: 'focus', sessionId: '', startedAt: '', endsAt: 0, remainingSec: 25 * 60, durationSec: 25 * 60, cycleCount: 0, subject: '', topic: '', notes: '', taskId: '' }, history: [] });
