    setStore(s => { const ns = { ...s, mistakes: s.mistakes.map(x => x.id === m.id ? { ...x, retries: x.retries + 1, lastReview: now, status: (correct ? 'resolved' : 'practicing') as Mistake['status'] } : x) }; return correct ? applyGamification(ns, gamEv) : ns; });
